script:
frappe.ui.form.on("Orden de Venta", {

    custom_quotation: function(frm) {

        if (!frm.doc.custom_quotation) return;

        frm.clear_table("custom_products");

        frappe.db.get_doc("CRM Deal", frm.doc.custom_quotation)
            .then(deal => {

                if (!deal.products || deal.products.length === 0) {
                    frappe.msgprint("El Deal no tiene productos registrados.");
                    return;
                }

                deal.products.forEach(row => {

                    let child = frm.add_child("custom_products");

                    child.product_code = row.product_code;
                    child.product_name = row.product_name;
                    child.custom_compañia = row.custom_compañia;
                    child.custom_categoria = row.custom_categoria;

                });

                frm.refresh_field("custom_products");
            });
    }
});
